SELECT DISTINCT
gsl.*, u.`user_name` AS userName,
u.nick_name AS nickName
FROM
sys_logs gsl
LEFT JOIN sys_user u ON u.id = gsl.user_id


        AND gsl.user_id = #{params.userId}


        AND gsl.module = #{params.model}


        AND gsl.operate = #{params.operate}


        AND u.`user_name` like CONCAT('%',#{params.userName},'%')


        AND gsl.operate_time  >=  #{params.operateStartTime}


        AND gsl.operate_time  <=  #{params.operateEndTime}



            AND gsl.consuming_time > #{params.consumingTime}


            AND gsl.consuming_time  >=  #{params.consumingTime}


            AND gsl.consuming_time = #{params.consumingTime}


            AND gsl.consuming_time  <  #{params.consumingTime}


            AND gsl.consuming_time  <=  #{params.consumingTime}



ORDER BY gsl.operate_time DESC
